from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=root/'dist/adventure.js'
s=p.read_text(encoding='utf-8-sig')
s=s.replace('let timer,dragged=null,audio;', 'let timer,dragged=null,audio;\nconst admin={active:false,backup:null};')
s=s.replace('function persist(){try', 'function persist(){if(admin.active)return;try')
s=s.replace('${header()}${world()}', '${header()}${admin.active?adminBar():\'\'}${world()}')
s=s.replace('<button class="verb ${verb===\'look\'?\'active\':\'\'}" data-act="verb" data-verb="look">Kijken</button>', '<button class="verb ${verb===\'look\'?\'active\':\'\'}" data-act="verb" data-verb="look">Verkennen</button><button class="verb ${verb===\'inspect\'?\'active\':\'\'}" data-act="verb" data-verb="inspect">Inspecteren</button>')
s=s.replace("function walkTo(x,y,callback=null){", "function cancelMovement(){goal=null;arrival=null;$('#player')?.classList.remove('walking');}\nfunction walkTo(x,y,callback=null){")
before="document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el){if(!el.disabled)acts[el.dataset.act]?.(el);return;}const scene=e.target.closest('#walk-scene');if(scene&&!e.target.closest('.interaction-tray')&&!panel.open){closeTray();const r=scene.getBoundingClientRect();walkTo((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height);scene.focus({preventScroll:true});}});"
assert before in s
after="document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el){if(!el.disabled){cancelMovement();acts[el.dataset.act]?.(el);}return;}const viewport=e.target.closest('.world-viewport'),scene=$('#walk-scene');if(viewport&&scene&&!e.target.closest('.interaction-tray,.place-view')&&!panel.open){cancelMovement();closeTray();closeInspection();const r=scene.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(verb==='inspect')inspectPlace(x,y);else walkTo(x,y);scene.focus({preventScroll:true});}});"
s=s.replace(before,after)
s=s.replace("function closeTray(){", "function closeInspection(){$('#place-inspection')?.remove();}\nfunction closeTray(){closeInspection();")
marker='function extraSpots(){'
assert marker in s
s=s.replace(marker, '''function inspectPlace(x,y){const c=cfg(),clamped={x:Math.max(0,Math.min(1,x)),y:Math.max(0,Math.min(1,y))},spots=extraSpots(),nearest=spots.map(t=>({t,d:Math.hypot(t.point[0]-clamped.x,t.point[1]-clamped.y)})).sort((a,b)=>a.d-b.d)[0],spot=nearest?.d<.19?nearest.t:null;const title=spot?.title||c.name,caption=spot?.observation||'Bekijk de ruimte van dichtbij. Zoek naar documenten, apparatuur en sporen; wat je aantreft kan een verklaring ondersteunen of juist ontkrachten.';const view=document.createElement('section');view.id='place-inspection';view.className='place-view';view.setAttribute('aria-label','Inspecteer '+title);view.innerHTML=`<div class="place-photo" style="background-image:url('${c.image}');background-position:${clamped.x*100}% ${clamped.y*100}%"></div><div class="place-caption"><p class="eyebrow">Je kijkt van dichtbij</p><h2>${esc(title)}</h2><p>${esc(caption)}</p>${spot?button('Onderzoek dit spoor','inspectSpot','btn-secondary',`data-id="${spot.id}"`):''}${button('Terug naar de kamer','closeInspection','btn-primary')}</div><button class="close" data-act="closeInspection" aria-label="Sluit inspectie">×</button>`;$('.world-viewport').append(view);view.querySelector('.close').focus({preventScroll:true});}
function adminBar(){return `<div class="admin-bar"><strong>Beheerpreview</strong><span>Je gewone voortgang blijft apart.</span>${button('Alle gebieden','adminOverview','btn-quiet')}${button('Inhoud controleren','adminContent','btn-quiet')}${button('Puzzel bekijken','adminFinal','btn-quiet')}${button('Terug naar mijn spel','adminExit','btn-quiet')}</div>`;}
function adminPrompt(){openPanel('Beheer van de adventure',`<p>Bekijk gebieden, theorie, gesprekken en puzzels rechtstreeks.</p><label class="notes-title" for="admin-code">Toegangscode</label><input id="admin-code" type="password" autocomplete="off" class="admin-code"><div class="panel-footer">${button('Open beheer','adminLogin')}</div><p id="admin-error" aria-live="polite"></p>`,'Ontwikkeloverzicht');}
function adminLogin(){if($('#admin-code')?.value!=='fabian1'){$('#admin-error').textContent='De code klopt niet.';return;}if(!admin.active){admin.backup=structuredClone(state);admin.active=true;}adminOverview();}
function adminOverview(){openPanel('Alle gebieden van de module',`<p>Open een gebied of bekijk de inhoud. Verkennen in deze preview verandert je gewone voortgang niet.</p>${book.chapters.map((ch,n)=>`<section class="admin-chapter"><p class="eyebrow">Les ${n+1}</p><h3>${esc(ch.title||campaign.chapters[n]?.title)}</h3><div class="room-map">${ch.investigations.map((i,k)=>`<button class="map-room" data-act="adminVisit" data-chapter="${n}" data-index="${k}"><img src="${rooms[k%rooms.length].image}" alt=""><div><h3>${esc(i.title||i.world?.name||campaign.chapters[n]?.investigations[k]?.title||i.id)}</h3><p>${i.beats.length} onderzoeksmomenten · ${i.finale.slots.length} puzzelverbanden</p></div></button>`).join('')}</div></section>`).join('')}${campaign.chapters.slice(book.chapters.length).map((ch,n)=>`<section class="admin-chapter"><h3>Les ${book.chapters.length+n+1} · ${esc(ch.title)}</h3><p>De adventure wordt gebouwd. De volledige oorspronkelijke les is beschikbaar via Naslag.</p></section>`).join('')}`,'Beheerpreview');}
function adminVisit(b){if(!admin.active)return;state.chapter=Number(b.dataset.chapter);state.room=Number(b.dataset.index);state.started=true;state.tools=tools.map(t=>t.id);actor={x:.5,y:.85};panel.close();render();}
function adminContent(){if(!admin.active)return;const i=inv();openPanel('Inhoud van '+cfg().name,`<p>Controleer hoe broninhoud, wereldbewijs en opdrachten met elkaar samenhangen.</p>${i.beats.map(b=>`<details class="admin-content-item"><summary>${esc(b.title)} · ${esc(b.type)}</summary><p>${esc(b.intro)}</p><p><strong>Begrippen:</strong> ${b.concepts.map(esc).join(' · ')}</p>${(b.reveal||[]).map(x=>`<article><h3>${esc(x.title||x.label)}</h3><p>${esc(x.text)}</p></article>`).join('')}<p><strong>Ondersteuning:</strong> ${esc(b.hint)}</p><p><strong>Uitleg na de handeling:</strong> ${esc(b.explainAfter)}</p><p><strong>Brononderdelen:</strong> ${b.sourceBlocks.map(esc).join(' · ')}</p>${button('Bekijk de interactie','adminBeat','btn-secondary',`data-id="${b.id}"`)}</details>`).join('')}`,'Theorie & uitvoering');}
function adminBeat(b){if(!admin.active)return;const beat=inv().beats.find(x=>x.id===b.dataset.id);if(!beat)return;const needed=requiredTool(beat);if(needed){selectedTool=needed;verb='use';}panel.close();openBeat(beat);}
function adminFinal(){if(!admin.active)return;inv().beats.forEach(b=>collect(state,b));beginFinale();}
function adminExit(){if(!admin.active)return;state=admin.backup;admin.active=false;admin.backup=null;panel.close();render();}
''' + marker)
s=s.replace("${button('Een nieuw onderzoek beginnen','resetPrompt','btn-quiet')}", "${button('Een nieuw onderzoek beginnen','resetPrompt','btn-quiet')}${button('Beheer van alle gebieden','adminPrompt','btn-secondary')}")
s=s.replace("const acts={start:", "const acts={adminPrompt,adminLogin,adminOverview,adminVisit,adminContent,adminBeat,adminFinal,adminExit,closeInspection,inspectSpot:b=>{closeInspection();approachExtra(b.dataset.id);},start:")
s=s.replace("document.addEventListener('keydown',e=>{if(!state", "document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='admin-code'){e.preventDefault();adminLogin();return;}if(!state")
