    f.write('''\n.admin-bar{display:flex;align-items:center;gap:12px;padding:7px 24px;background:#655430;color:#fff0cf;font-size:.65rem;flex-wrap:wrap}.admin-bar .btn{padding:5px 9px;font-size:.65rem;color:#fff0cf}.admin-code{display:block;width:min(100%,350px);background:#fffaf0;border:1px solid #9da88d;border-radius:5px;padding:12px;color:var(--ink);font-size:1rem}.admin-content-item{border-top:1px solid #b9c4aa;padding:18px 0}.admin-content-item summary{cursor:pointer;font-weight:600}.admin-content-item article{background:#e7ead7;padding:15px;margin:10px 0;border-radius:4px}.admin-content-item h3{font-size:1.2rem}.admin-chapter{margin:30px 0}.place-view{position:absolute;inset:4%;z-index:25;background:#f1ead8;border:1px solid #d8c997;border-radius:7px;box-shadow:0 16px 60px #0008;display:flex;flex-direction:column;overflow:hidden;color:var(--ink)}.place-photo{flex:1;min-height:140px;background-size:260%;background-repeat:no-repeat}.place-caption{padding:17px 23px;max-height:46%;overflow:auto}.place-caption .eyebrow{font-size:.58rem;color:#927140;margin-bottom:6px}.place-caption h2{font-size:1.4rem;margin-bottom:8px}.place-caption p{font-size:.8rem;line-height:1.55}.place-caption .btn{font-size:.7rem;padding:10px 13px;margin-right:8px;background:var(--ink);color:#f4ead3}.place-view>.close{position:absolute;right:10px;top:10px;background:#f1ead8;color:var(--ink)}@media(max-width:760px){.place-view{position:fixed;inset:12svh 5vw 10svh;z-index:85}.admin-bar{padding:10px 15px;gap:7px}.admin-bar span{display:none}.place-caption{max-height:55%;padding:16px}}\n''')
